import {randomName,NAME_BANK} from './names.js?v=0.5.0';
import {openMatchmaking,descendantCount} from './family.js?v=0.5.0';
import {UNITS,getUnit,unitHead,appointment} from './units.js?v=0.5.0';
import {avatar,grade,nationalStanding,POPULATION,familySummary} from './life.js?v=0.5.0';
import {announceAll,clearAnnouncements} from './presentation.js?v=0.5.0';
import {KEYS,RANKS,OFFICES,PLACES,EDUCATION,ACTIVITIES,create,selectPartner,endMarriage,age,career,event,advance,decide,migrate,chooseEducation,school,location,degreeRate,retirementLimit,healthRisk,eraseMistake,exchangeLifespan,hintStage} from './engine.js?v=0.5.0';
import * as audio from './audio.js?v=0.5.0';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE='qingyun-save-v5';let state=null,activity=0,speed=1,allocation=[20,20,20,20,20],toastTimer;
try{const saved=localStorage.getItem(STORAGE)||localStorage.getItem('qingyun-save-v4')||localStorage.getItem('qingyun-save-v3')||localStorage.getItem('qingyun-save-v2')||localStorage.getItem('qingyun-save-v1');if(saved)state=migrate(JSON.parse(saved));}catch{toast('存档读取失败，原文件仍保留，可导入备份或开始新人生。');}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').style.display='block';toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{toast('自动保存失败，请导出备份。');}}
function modal(html){const el=$('#modal');el.oncancel=null;if(el.open)el.close();el.innerHTML=html+'<div class="divider"></div><button id="close-dialog" class="primary">继续旅程</button>';el.showModal();$('#close-dialog').onclick=()=>el.close();}
function signals(){audio.syncBackground(state);const spoken=state.lastAnnouncements||[];announceAll(spoken);for(const type of state.lastSignals){if(type==='family')continue;if(!spoken.some(a=>a.type===type))audio.playMilestone(type).catch(()=>toast('音效播放失败，可在音乐设置中重试。'));}state.lastSignals=[];state.lastAnnouncements=[];}
function bindHeader(){ $('#help').onclick=help;$('#music-settings').onclick=musicSettings;$('#music-toggle').onclick=async()=>{try{await audio.enableMusic(!audio.isEnabled());if(state)audio.syncBackground(state);updateAudioHeader();}catch{toast('浏览器未启用声音，请点击后重试。');}};updateAudioHeader();}
function updateAudioHeader(){ $('#music-toggle').textContent=audio.isEnabled()?'♫ 音乐已开':'♫ 开启音乐';$('#music-toggle').setAttribute('aria-pressed',String(audio.isEnabled()));}
function help(){modal(`<button id="tutorial-again" class="smallbtn">重新查看入门教程</button><span class="eyebrow">VOLUME V · 成长有声</span><h2>一生不止一条路。</h2><p>第五版姓名库含25,056个不重复姓名，混合两字、三字与少量复姓；角色、伴侣、亲属与官员共用。年度题库128题，以8个人类历史节点为依据，分别改写为16个年龄／官职场景。每个场景的8题用完前不重复，答案后可查历史来源与解析。升学／升迁插图下展示上一年的五维变化、重要里程碑与本年抉择，记录存入人生档案。</p><p>0–2岁为学前启蒙，不设年级。3岁幼儿园小班，4岁中班，5岁大班，6岁小学一年级。国家总人口15亿。</p><p>22岁起可从三位候选人中自主挑选伴侣，也可暂不考虑；可主动离婚与再婚。父母、祖辈、伴侣、子女、姻亲与后代都有独立年龄和健康状态，可能患病、康复、因病或意外离世。子女22岁后可随机结婚，两位家长22–48岁且存活时可能生育，继续繁衍孙辈、重孙辈等。后代的家庭支持使任职成长适度加速，最高加成8%。</p><p>单位名录按虚构省、市、县和部门生成，共5392个不同单位。官职包括科员、科长、处长、局长、厅长、部长等；与职级和领导职务层次分别展示。任职往来可结识各级官员。重大变动雷声采用MorningGloryProductions的CC0真实录音，来源见音乐署名。</p><p>播报：每次升年级、毕业、入学与晋升有中文喜报播音；重大变动搭配雷声与闪电。播音使用浏览器／系统语音，未安装中文语音时保留文字与音乐。可在音乐设置关闭播音；减少动态效果的系统设置会自动关闭闪电。</p><p>成年后自主择偶，婚后可能分开或丧偶，子女随机出生，家庭事务与配偶支持带来有限的晋升波动。男女使用相同数值规则。全国排名基于虚构15亿人口的五维与职务模拟，不是在线玩家榜；在任国家主席固定第一名。</p><p>从学前到博士，初中、高中、本科和硕士毕业后可自主决定是否升学。初中毕业可先在实践中心准备，18岁后任职；高中18岁、本科22岁、硕士25岁、博士29岁毕业。本科／硕士／博士的任职成长速度分别为1.12／1.24／1.36倍，其余为1倍。</p><p>背景音乐随年龄、学生／任职和退休状态切换；升学、升迁、仙值与退休提示使用独立音效。前景音效依次播放，背景自动降低音量。金手指少年（18岁前）、成年（18–59岁）、晚年（60岁起）各有独立曲库，使用不限次。</p><p>日／周／月／年观察收益100%／85%／68%／50%，属性每天照常成长。每个生日必须完成年度决策，升学选择也不会被快进跳过。</p><p>五维无100上限。体是基础，劳是实践途径，德决定方向，智提供能力，美丰富精神。五维全部超过100觉醒，立即获得仙值；保持五维破百每365天再获仙值。任一维度达到1000后永久十倍获取（觉醒奖励与年度奖励均由1点变10点，不叠加）；同时解锁1点仙值兑换1岁寿命，上限150岁。兑换不复活，不消除疾病风险，不改变退休年龄。1点仍可抹去一次失误。</p><p>体力低于25会有随机患病风险，患病且持续低体力时可能因病死亡。身体力行能提升体力并加快康复。40岁后体力随年龄逐日衰减，65岁后衰减加快。此为游戏数值。</p><p>退休年龄：基层60、厅局65、省部70、国家级80。达到当前层级退休年龄即办理退休，先退休后不再晋升；退休后仍可生活至寿终或因病结束。无失误、健康存活的路线基准目标为 min(寿命×80%, 72岁)，高学历可更早到达。</p><p>所有地区、学校、人物与任职规则均为虚构；12职级与10层领导职务分开展示。<a href="https://www.gov.cn/xinwen/2019-03/27/content_5377422.htm" target="_blank" rel="noreferrer">职级名称参考 ↗</a></p><p>第一版存档会自动迁移，原始v1存档保留。旧角色22岁以后按本科经历兼容。当前为本地单机游戏。</p>`);$('#tutorial-again').onclick=tutorial;}
function musicSettings(){const src=audio.musicSources();modal(`<span class="eyebrow">SOUND STUDIO</span><h2>音乐与短剧原声</h2><p class="sub">背景、金手指、里程碑为三个独立声道，前景队列避免互相覆盖。总音量 <output id="volume-value">${Math.round(audio.getVolume()*100)}%</output></p><input id="volume" aria-label="总音量" type="range" min="0" max="100" value="${audio.getVolume()*100}"><p class="music-notice">热门短剧原声尚未内置：目前未取得可直接用于本游戏的音源。默认是原创替代配乐，不是热榜原曲。可导入本地音频（仅当前会话），或填写可使用的HTTPS音频直链。公开热度与情绪标签需人工核实。</p><p class="sub">正向：${audio.MOOD_ANALYSIS.positive}<br>负向：${audio.MOOD_ANALYSIS.negative}</p><div class="sound-library">${audio.AGE_POOLS.map((stage,i)=>`<h3>${stage}曲库 · ${['0–17岁','18–59岁','60岁以上'][i]}</h3>${['positive','negative'].map(mood=>`<div class="sound-source"><label>${mood==='positive'?'正向 · 激昂／希望':'负向 · 悲伤／代价'}<input type="text" data-url="${i}-${mood}" placeholder="HTTPS 音频链接" value="${esc(src[stage+'-'+mood]||'')}"></label><div class="row"><label class="file-label">导入本地音频<input type="file" accept="audio/*" data-file="${i}-${mood}"></label><button class="smallbtn" data-demo="${i}-${mood}">试听</button></div><p class="sub" data-source-label="${i}-${mood}">${esc(audio.sourceLabel(stage,mood))}</p></div>`).join('')}`).join('')}</div><button id="save-music" class="primary">保存音源设置</button><p class="sub">原声每次最多播放15秒。远程音源加载失败会明确报错，不会假装已播放原声。背景页会暂停播放。</p><div class="divider"></div><h3>开放背景音乐与署名</h3><p class="sub">当前背景曲：${esc(audio.backgroundTrack())}。完整曲目连续播放，播音期间自动降低音量，年龄阶段变化时换曲。</p>${audio.TRACKS.map(t=>`<p class="sub"><a href="${t.source}" target="_blank" rel="noreferrer">${t.title}</a> — Kevin MacLeod (incompetech.com)。<a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>。改动：循环播放、调整音量；原曲旋律不变。</p>`).join('')}<p class="sub">真实雷声：Thunder — MorningGloryProductions，CC0。<a href="https://freesound.org/people/MorningGloryProductions/sounds/195344/" target="_blank" rel="noreferrer">录音与许可来源 ↗</a></p><button id="test-thunder" class="smallbtn">试听真实雷声</button> <button id="stop-thunder" class="smallbtn">停止雷声</button><label><input id="narration" type="checkbox" ${audio.narrationEnabled()?'checked':''}> 开启中文喜报播音</label><a href="https://music.douyin.com/qishui/share/playlist?playlist_id=7640848489467166770" target="_blank" rel="noreferrer">平台公开BGM歌单参考 ↗</a>`);
$('#test-thunder').onclick=async()=>{if(!audio.isEnabled())await audio.enableMusic(true);audio.previewThunder();updateAudioHeader();};$('#stop-thunder').onclick=audio.stopThunder;
$('#narration').onchange=e=>audio.setNarration(e.target.checked);
$('#volume').oninput=e=>{audio.setVolume(+e.target.value/100);$('#volume-value').textContent=e.target.value+'%';};
document.querySelectorAll('[data-file]').forEach(el=>el.onchange=()=>{const [i,mood]=el.dataset.file.split('-'),file=el.files[0];if(file){audio.setLocalMusic(audio.AGE_POOLS[+i],mood,file);$(`[data-source-label="${el.dataset.file}"]`).textContent=audio.sourceLabel(audio.AGE_POOLS[+i],mood);toast('本地音频已接入当前会话');}});
document.querySelectorAll('[data-demo]').forEach(el=>el.onclick=async()=>{const [i,mood]=el.dataset.demo.split('-');try{if(!audio.isEnabled())await audio.enableMusic(true);audio.stopForeground();await audio.playHint(mood==='positive',audio.AGE_POOLS[+i]);updateAudioHeader();}catch(e){toast(e.message);}});
$('#save-music').onclick=()=>{try{const entries=[...document.querySelectorAll('[data-url]')].map(el=>{const [i,mood]=el.dataset.url.split('-');const url=el.value.trim();if(url&&!/^https:\/\//i.test(url))throw Error('请填写HTTPS音频链接');return [audio.AGE_POOLS[+i],mood,url];});entries.forEach(x=>audio.configureMusic(...x));toast('六个年龄／情绪音源已保存');}catch(e){toast(e.message);}};
}
function setup(){ $('#app').innerHTML=`<div class="intro"><section class="intro-copy"><span class="eyebrow">卷五 · 观史明志，仙途延年</span><h1>一生向上，<br>也要听见沿途。</h1><p>从云溪镇的第一声啼哭，到大学校园的朗朗书声，再到为山河承担责任。你的学业、身体与每一次抉择，写下不同的人生。</p><div class="divider"></div><div class="row sub"><span>01 / 学有所成</span><span>02 / 躬身入局</span><span>03 / 归田有声</span></div><div class="landscape" aria-hidden="true"><div class="mountain"></div><div class="mountain"></div></div></section><section class="card"><div class="row"><h2>开启一段人生</h2><button id="random" class="smallbtn">↻ 随机角色</button></div><div class="form-grid"><label>角色姓名<input type="text" id="name" maxlength="20" value="林知远"></label><label>预期寿命 · 岁<input type="number" id="life" min="70" max="110" value="90"></label></div><div class="identity-picker"><div id="avatar-preview" class="avatar-preview">${avatar({day:0,gender:'男',avatarVariant:0})}</div><div><label>性别<select id="gender"><option>男</option><option>女</option></select></label><label>头像<select id="avatar-variant"><option value="0">暖杏</option><option value="1">麦色</option><option value="2">浅玉</option></select></label></div></div><label class="section-label">出生地区<select id="place">${PLACES.map((p,i)=>`<option value="${i}">${p.province} · ${p.city} · ${p.county} · ${p.town}</option>`).join('')}</select></label><div class="divider"></div><div class="row"><h3>五维禀赋</h3><span class="sub">初始总点数 <b id="total">100</b> / 100</span></div>${KEYS.map((k,i)=>`<div class="stat-input"><label for="stat${i}">${k}</label><input type="range" min="5" max="60" value="20" id="stat${i}" data-stat="${i}"><output id="out${i}">20</output></div>`).join('')}<p class="sub">初始总点数相同，成长不设100上限。体力低于25存在患病风险。</p><div class="divider"></div><h3>♫ 闻弦知意</h3><p class="sub">少年／成年／晚年三曲库 · 使用不限次<br>默认原创替代配乐，热门原声可在音乐设置接入。</p><p class="error" id="error" role="alert"></p><button class="primary advance" id="begin">落笔人生 · 开启音乐 →</button><button id="import-start" class="advance">导入已有存档（兼容第一版）</button></section></div>`;
const preview=()=>$('#avatar-preview').innerHTML=avatar({day:0,gender:$('#gender').value,avatarVariant:+$('#avatar-variant').value});$('#gender').onchange=preview;$('#avatar-variant').onchange=preview;
document.querySelectorAll('[data-stat]').forEach(el=>el.oninput=()=>{allocation[+el.dataset.stat]=+el.value;$('#out'+el.dataset.stat).value=el.value;$('#total').textContent=allocation.reduce((a,b)=>a+b,0);});
$('#random').onclick=()=>{allocation=[5,5,5,5,5];for(let n=0;n<75;n++){let i=Math.floor(Math.random()*5);while(allocation[i]>=60)i=(i+1)%5;allocation[i]++;}allocation.forEach((x,i)=>{$('#stat'+i).value=x;$('#out'+i).value=x;});$('#total').textContent=100;$('#place').value=Math.floor(Math.random()*PLACES.length);$('#gender').value=Math.random()<.5?'男':'女';$('#avatar-variant').value=Math.floor(Math.random()*3);preview();$('#name').value=randomName();};
$('#begin').onclick=async()=>{try{state=create($('#name').value,allocation,+$('#life').value,Date.now()>>>0,+$('#place').value,$('#gender').value,+$('#avatar-variant').value);}catch(e){$('#error').textContent=e.message;return;}audio.stopForeground();audio.syncBackground(state);try{await audio.enableMusic(true);}catch{toast('点击页首「开启音乐」即可听见背景音乐。');}save();render();updateAudioHeader();tutorial();};$('#import-start').onclick=importSave;
}
function activityNames(){return age(state)<3?['亲子共读','规律作息','感官探索','亲情回应','听音识色']:age(state)<6?['绘本启蒙','户外游戏','收纳种植','分享合作','涂画听歌']:ACTIVITIES.map(x=>x.name);}
function render(){if(!state)return setup();audio.syncBackground(state);const c=career(state),a=age(state),e=state.pending?event(state):null,names=activityNames(),risk=healthRisk(state),target=Math.min(72,Math.floor(state.lifespan*.8)),standing=nationalStanding(state),family=familySummary(state),job=appointment(state);
$('#app').innerHTML=`<div class="title-row"><div><span class="eyebrow">VOLUME V · ${audio.musicEra(state)}篇</span><h1>人生纪事 <span class="gold">·</span> ${state.retired?'归田岁月':state.stage!=='work'?EDUCATION[state.stage].name:c.progress>=1?'山河在肩':'躬身入局'}</h1></div><div class="tools"><button id="archive" class="smallbtn">人生档案</button><button id="export" class="smallbtn">导出</button><button id="import" class="smallbtn">导入</button><button id="reset" class="smallbtn">新的人生</button></div></div>
${state.ended?`<div class="ended"><span class="eyebrow">THE FINAL CHAPTER</span><h2>${state.deathReason==='寿终'?'一生走过，山河有记。':'命运无常，余音未歇。'}</h2><p>${esc(state.deathReason)} · ${a}岁 ${state.day%365}天 · ${esc(c.office)}</p></div>`:''}
<div class="grid"><aside><section class="card profile"><div class="portrait portrait-svg">${avatar(state)}</div><h2>${esc(state.name)}</h2><span class="sub">澄川公民 · ${state.gender} · ${a}岁 ${state.day%365}天</span><div><span class="badge">${esc(c.rank)}</span></div><p class="place-label">${esc(location(state))}</p><div class="metric"><div><b>${Math.floor(state.merit).toLocaleString()}</b><span class="sub">履历积累</span></div><div><b>${state.correct}/${state.decisions}</b><span class="sub">正确抉择</span></div></div><div class="divider"></div>${KEYS.map((k,i)=>`<div class="attribute"><div class="row"><span>${k} <small class="sub">${['方向','能力','基础','精神','实践'][i]}</small></span><b class="${state.stats[i]>100?'gold':''}">${state.stats[i].toFixed(1)}</b></div><div class="bar"><i style="width:${Math.min(100,state.stats[i])}%"></i></div></div>`).join('')}<div class="health-box ${risk?'at-risk':''}"><b>${state.illness?'患病休养 · 剩余'+state.illness+'恢复单位':risk?'低体力 · 存在患病风险':'身体状态平稳'}</b><span>体力阈值25 · ${a>=40?'当前有年龄衰减':'坚持活动，积累健康基础'}</span></div><p class="quote">以体为基，以劳为径。<br>以德为向，以智为翼，以美润心。</p></section></aside>
<section><div class="hero card"><span class="eyebrow">${state.stage!=='work'?'当前就读／实践地点':state.retired?'退休生活':'当前领导职务'}</span><h2>${esc(state.stage!=='work'?school(state):job.title)}</h2><p>${esc(location(state))}${state.stage==='work'?' · '+esc(c.office):''}</p><div class="row sub" style="color:#c4d4c4"><span>学历：${esc(state.degree)}${state.stage!=='work'?' · '+grade(state):''}</span><span>数字级别 ${c.level}${state.stage==='work'?'级':''}</span></div><div class="bar"><i style="width:${state.day/(state.lifespan*365)*100}%"></i></div><p class="hero-caption">${state.retired?state.retirementAge+'岁退休，保留原职务记录。':state.stage==='work'?'任职 '+state.service.toFixed(1)+' 年 · 当前层级退休年龄 '+retirementLimit(state)+' 岁':'升学与毕业时会暂停，等待你的选择。'}</p></div>
${state.familyChoice?partnerPanel():''}${state.transition?`<section class="card section education-choice"><span class="event-tag">人生岔路 · 毕业选择</span><h2>${EDUCATION[state.transition.completed].name}毕业了</h2><p>最高学历：${state.degree}。继续进入${EDUCATION[state.transition.next].name}，或走向实践与公共岗位。</p><div class="choices"><button id="study" class="primary">继续升学 · ${EDUCATION[state.transition.next].name} →</button><button id="work">${a<18?'进入青年实践中心 · 18岁任职':'进入公共岗位 · 从二级科员起步'}</button></div><p class="sub">求学或实践，由你选择。人生的每条路，都有自己的风景。</p></section>`:e?`<section class="card section event-card"><span class="event-tag">第 ${a} 年 · ${esc(e.context)}</span><h2>${esc(e.title)}</h2><p class="sub">${esc(location(state))}</p><p>${esc(e.text)}</p><div class="choices">${e.options.map((o,i)=>`<div class="choice"><button data-choice="${i}">${'ABC'[i]} · ${esc(o)}</button><button class="listen" data-listen="${i}" aria-label="试听选项${'ABC'[i]}的背景音乐">♫ 试听</button></div>`).join('')}</div><p class="sub">${hintStage(state)}金手指 · 使用不限次 · 正向明亮／负向悲伤<br>当前默认替代配乐；原声可在音乐设置中接入。</p><button id="stop-hint" class="smallbtn">停止前景音乐</button></section>`:!state.ended?`<section class="section"><div class="section-head"><h2>${a<6?'今日成长':state.retired?'今日生活':'今日修行'}</h2><span class="sub">一项活动 · 五维共生</span></div><div class="actions">${ACTIVITIES.map((x,i)=>`<button class="activity ${i===activity?'selected':''}" data-activity="${i}"><b>${x.icon}</b>${names[i]}</button>`).join('')}</div><p class="sub">${state.illness?'建议运动休养类活动，加快恢复。':a<6?'在家人的陪伴下，每一天都有新的发现。':ACTIVITIES[activity].desc}</p><div class="card"><div class="section-head"><h3>时光的步幅</h3><span class="sub">观察收益 ${speed===1?'100':speed===7?'85':speed===30?'68':'50'}%</span></div><div class="speed">${[1,7,30,365].map((n,i)=>`<button data-speed="${n}" class="${speed===n?'selected':''}">${['一天','一周','一月','一年'][i]}</button>`).join('')}</div><button id="advance" class="primary advance" ${state.familyChoice?'disabled':''}>${names[activity]} · 推进${speed===1?'一天':speed===7?'一周':speed===30?'一月':'一年'} →</button><p class="sub">每日结算成长和疾病风险；年度抉择、升学选择前自动暂停。</p></div></section>`:''}
<section class="section card"><div class="section-head"><h3>人生手记</h3><span class="sub">最近的足迹</span></div><div class="timeline">${state.logs.length?state.logs.map(l=>`<div class="log"><time>${Math.floor(l.day/365)}岁 · 第${l.day%365}天</time>${esc(l.text)}</div>`).join(''):'<p class="sub">你出生在'+esc(PLACES[state.place].town)+'，故事从这个平凡清晨开始。</p>'}</div></section></section>
<aside class="right"><section class="card standing-card"><span class="eyebrow">AMONG THE PEOPLE</span><h3>${standing.label}</h3><strong class="national-rank">第 ${standing.rank.toLocaleString()} 名</strong><p class="sub">澄川15亿人口中<br>超过 ${standing.percent.toFixed(standing.rank<=100?6:2)}% 的人<br>模拟人口分位 · 非在线玩家排名</p></section><section class="card section family-card"><span class="eyebrow">A LIFE TOGETHER</span><h3>家有余温 · ${family.status}</h3><p class="sub">${esc(family.spouse)}</p><p class="sub">${family.children.length?family.children.map(c=>`${esc(c.name)} · ${c.gender==='男'?'儿子':'女儿'} · ${c.age}岁 · ${c.alive===false?'已故':c.illness?'患病':'平安'}`).join('<br>'):'子女缘分尚未到来'}</p><p class="sub">在世后代 ${family.descendants} 位 · 亲属 ${family.relatives.length} 位</p><div class="tools"><button id="family-archive" class="smallbtn">家族与亲属 ↗</button>${!state.ended&&a>=22&&state.maritalStatus!=='married'?'<button id="matchmaker" class="smallbtn">挑选伴侣</button>':''}${!state.ended&&state.maritalStatus==='married'?'<button id="divorce" class="smallbtn">办理离婚</button>':''}</div></section><section class="card section"><span class="eyebrow">THE LONG ROAD</span><h3>${state.stage==='work'?'青云阶梯':'求学之路'}</h3><div class="rank-list">${(state.stage==='work'?RANKS:Object.entries(EDUCATION).filter(([k])=>!['work','preparation'].includes(k)).map(([,v])=>v.name)).map((r,i)=>`<div class="rank ${r===c.rank?'active':''}">${String(i+1).padStart(2,'0')}　${r}${r===c.rank?' ←':''}</div>`).join('')}</div><div class="divider"></div><h3 class="gold">国家主席</h3><p class="sub">以每一天的担当，走向更远的山河。</p><div class="bar"><i style="width:${c.progress*100}%"></i></div><p class="sub">进度 ${Math.floor(c.progress*100)}%</p><div class="tools"><button id="offices" class="smallbtn">职级与职务 ↗</button><button id="units" class="smallbtn">单位名录 ↗</button><button id="contacts" class="smallbtn">相识官员 ${state.contacts.length}</button></div></section>
<section class="card section xian-card"><span class="eyebrow">BEYOND A HUNDRED</span><h3>仙值 <b class="gold">${state.xianUnlocked?state.xian:'未觉醒'}</b></h3><p class="sub">五维全部超过100觉醒。保持破百每年获得${state.xianAccelerated?10:1}点；任一维度达到1000后永久十倍，并可兑换寿命。</p><p class="sub">当前失误 ${state.mistakes} · 已抹去 ${state.erased}</p><button id="erase" class="smallbtn" ${state.xian<1||state.mistakes<1||state.ended?'disabled':''}>消耗1点 · 抹去一次失误</button><div class="divider"></div><p class="sub">${state.xianAccelerated?'仙途进阶已解锁 · 仙值获取 ×10':'任一维度达到1000，解锁仙途进阶'}<br>预期寿命 ${state.lifespan}岁 · 已兑换 ${state.lifespanExchanged}岁<br>1仙值＝1岁 · 寿命上限150岁</p><button id="exchange-life" class="smallbtn" ${!state.xianAccelerated||state.xian<1||state.lifespan>=150||state.ended?'disabled':''}>消耗1点 · 延寿1年</button></section>
<section class="card section"><span class="eyebrow">SOUND OF DESTINY</span><h3>♫ ${hintStage(state)} · 闻弦知意</h3><p class="sub">背景：${audio.musicEra(state)}<br>升学／升迁独立音效 · 背景自动让位<br>热门原声未内置，可配置音源</p><button id="sound-detail" class="smallbtn">曲库与音量设置 ↗</button></section></aside></div>`;
$('#export').onclick=exportSave;$('#import').onclick=importSave;$('#sound-detail').onclick=musicSettings;$('#archive').onclick=showArchive;$('#family-archive').onclick=showFamilyArchive;$('#units').onclick=showUnits;$('#contacts').onclick=showContacts;bindFamily();
$('#reset').onclick=()=>{modal('<h2>开启新的人生</h2><p>可先导出存档保留这段旅程。</p><button id="backup">导出当前存档</button> <button id="new-life">确认开启新人生</button>');$('#backup').onclick=exportSave;$('#new-life').onclick=()=>{clearAnnouncements();audio.stopForeground();audio.syncBackground({day:0,stage:'preschool',retired:false,ended:true});state=null;allocation=[20,20,20,20,20];try{localStorage.removeItem(STORAGE);localStorage.removeItem('qingyun-save-v4');localStorage.removeItem('qingyun-save-v3');localStorage.removeItem('qingyun-save-v2');localStorage.removeItem('qingyun-save-v1');}catch{}$('#modal').close();setup();};};
$('#offices').onclick=()=>modal('<h2>职级与领导职务</h2><p>两条序列分开展示。数字级别为27至1。</p><h3>职级</h3>'+RANKS.map(x=>`<div class="rank">${x}</div>`).join('')+'<h3>领导职务</h3>'+OFFICES.map(x=>`<div class="rank">${x}</div>`).join('')+'<p class="sub">此为虚构晋升规则，未模拟现实的职数、任期和选任程序。</p>');
$('#exchange-life').onclick=()=>{if(exchangeLifespan(state)){signals();save();render();toast('寿命延长1岁，当前预期寿命'+state.lifespan+'岁。');}};
$('#erase').onclick=()=>{if(eraseMistake(state)){save();render();toast('已抹去一次失误的晋升影响，下一次年度结算生效。');}};
document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{activity=+b.dataset.activity;render();});document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=+b.dataset.speed;render();});
if($('#advance'))$('#advance').onclick=()=>{advance(state,speed,activity);signals();save();render();};
if($('#study'))$('#study').onclick=()=>education(true);if($('#work'))$('#work').onclick=()=>education(false);
document.querySelectorAll('[data-listen]').forEach(b=>b.onclick=async()=>{try{if(!audio.isEnabled()){await audio.enableMusic(true);updateAudioHeader();}audio.stopForeground();const positive=+b.dataset.listen===e.answer;toast(hintStage(state)+'曲库 · '+audio.sourceLabel(hintStage(state),positive?'positive':'negative'));await audio.playHint(positive,hintStage(state));}catch(err){toast(err.message||'音乐播放失败，请检查音源。');}});
document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{audio.stopForeground();const result=decide(state,+b.dataset.choice);signals();save();render();modal(`<span class="eyebrow">ANNUAL REVIEW · ${result.age}</span><h2>${result.ok?'方向正确，向上一步。':'走过弯路，也留下思考。'}</h2><p>${esc(result.choice)}</p><p>${esc(result.report)}</p>${reviewHTML({age:result.age,lines:result.changes||[]})}${historyHTML(result)}<p class="gold">履历 +${result.ok?100:20}${result.ok?' · 五维各 +0.6':''}</p>${state.transition?'<p>毕业后的选择正在等待你，关闭年报即可继续。</p>':''}`);});if($('#stop-hint'))$('#stop-hint').onclick=audio.stopForeground;
}
function education(yes){chooseEducation(state,yes);signals();save();render();toast(yes?'新的校园篇章已开启':'新的实践与任职篇章已开启');}
function showArchive(){modal(`<span class="eyebrow">LIFE ARCHIVE</span><h2>${esc(state.name)}的人生档案</h2><p>${esc(location(state))} · 最高学历${state.degree} · 已患病${state.illnesses}次</p><h3>家庭与亲人</h3><p>${familySummary(state).status} · ${esc(familySummary(state).spouse)}</p>${familySummary(state).children.map(c=>`<div class="rank">${esc(c.name)} · ${c.gender} · ${c.age}岁</div>`).join('')}<h3>求学经历</h3>${state.educationHistory.map(h=>`<div class="rank">${h.age}岁 · ${esc(h.school)} · 毕业</div>`).join('')||'<p class="sub">成长才刚刚开始。</p>'}<h3>重要里程碑</h3>${state.milestones.map(m=>`<div class="rank">${Math.floor(m.day/365)}岁 · ${esc(m.text)}</div>`).join('')||'<p class="sub">每一步都值得记下。</p>'}<h3>年度决策</h3>${state.history.map(h=>`<div class="rank">${h.age}岁 · ${esc(h.title)} · ${h.ok?'正确':h.erased?'失误已抹去':'失误'}<br>${esc(h.choice)}${historyHTML(h)}${reviewHTML({age:h.age,lines:h.changes||[]})}</div>`).join('')}`);}
function exportSave(){if(!state)return;const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='qingyun-v5-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files[0];if(!f||f.size>2000000)throw Error();const next=migrate(JSON.parse(await f.text()));clearAnnouncements();audio.stopForeground();state=next;state.lastSignals=[];state.lastAnnouncements=[];save();render();toast('存档已载入，兼容数据已迁移');}catch{toast('导入失败，请使用有效的青云纪存档。');}};input.click();}
document.addEventListener('visibilitychange',()=>{if(document.hidden)audio.pauseForVisibility();else audio.resumeForVisibility().catch(()=>{});});
window.addEventListener('qingyun-audio-warning',e=>toast(e.detail));
bindHeader();render();if(state&&!state.tutorialDone)queueMicrotask(tutorial);

function partnerPanel(){return `<section class="card section partner-panel"><span class="eyebrow">缘分由你选择</span><h2>挑选你的${state.gender==='男'?'妻子':'丈夫'}</h2><p class="sub">了解彼此的年纪、性格、工作和健康，再决定是否携手。</p><div class="partner-options">${state.familyChoice.candidates.map((p,i)=>`<article><div class="candidate-avatar">${avatar({gender:p.gender,avatarVariant:i,day:(age(state)-p.bornAt)*365})}</div><h3>${esc(p.name)}</h3><p>${age(state)-p.bornAt}岁 · ${esc(p.occupation)}<br>${esc(p.trait)} · 健康${p.health>=70?'良好':'平稳'}</p><button class="primary" data-partner="${esc(p.id)}">选择${esc(p.name)}</button></article>`).join('')}</div><button id="decline-partners" class="smallbtn">暂不考虑 · 继续人生</button></section>`;}
function bindFamily(){document.querySelectorAll('[data-partner]').forEach(b=>b.onclick=()=>{if(selectPartner(state,b.dataset.partner)){signals();save();render();}});if($('#decline-partners'))$('#decline-partners').onclick=()=>{selectPartner(state,null);save();render();};if($('#matchmaker'))$('#matchmaker').onclick=()=>{if(openMatchmaking(state)){save();render();}};if($('#divorce'))$('#divorce').onclick=()=>{modal(`<h2>办理离婚</h2><p>与${esc(state.spouse.name)}结束婚姻后，子女和亲属关系记录会保留，双方均可继续生活。此后可以重新选择伴侣。</p><button id="confirm-divorce">确认协商离婚</button>`);$('#confirm-divorce').onclick=()=>{if(endMarriage(state)){$('#modal').close();signals();save();render();}};};}
function showFamilyArchive(){const f=familySummary(state);modal(`<span class="eyebrow">FAMILY TREE</span><h2>${esc(state.name)}的家族</h2><p>${f.status} · 在世亲属 ${f.relatives.filter(r=>r.alive).length} 位 · 在世后代 ${f.descendants} 位</p><p class="sub">亲属独立经历衰老、疾病、康复与离世；后代成年后可以成家，谱系持续保留。</p><div class="family-tree">${[...f.relatives].sort((a,b)=>a.generation-b.generation||a.bornAt-b.bornAt).map(r=>`<article style="margin-left:${Math.max(0,Math.min(4,r.generation))*12}px"><div class="mini-avatar">${avatar({gender:r.gender,day:r.age*365,avatarVariant:Math.abs(r.bornAt)%3})}</div><div><b>${esc(r.name)}</b> · ${esc(r.relation)}<br><span class="sub">${r.alive?r.age+'岁':'享年'+r.age+'岁'} · ${r.gender} · ${r.healthLabel} · ${({single:'未婚',married:'已婚',divorced:'离异',widowed:'丧偶'})[r.maritalStatus]}${r.partnerId&&r.partnerId!=='self'?' · 配偶 '+esc(f.relatives.find(p=>p.id===r.partnerId)?.name||''):''}${r.parentIds.length?'<br>父母：'+r.parentIds.map(id=>id==='self'?esc(state.name):esc(f.relatives.find(p=>p.id===id)?.name||'')).join('、'):''}${!r.alive?' · '+esc(r.deathReason):''}</span></div></article>`).join('')}</div>`);}
function showContacts(){modal(`<span class="eyebrow">PUBLIC SERVICE NETWORK</span><h2>相识官员</h2><p class="sub">随任职往来结识人物，展示姓名、职称和单位。均为虚构人物。</p>${state.contacts.length?state.contacts.map(c=>`<article class="contact-row"><b>${esc(c.name)}${esc(c.title)}</b><p class="sub">${esc(getUnit(c.unitId)?.name||'原任单位')} · ${c.metAt}岁时相识</p></article>`).join(''):'<p>尚未任职或尚无工作往来，未来会陆续结识各级官员。</p>'}<p class="sub">职称示例：科长、处长、局长、厅长、部长及其副职。</p>`);}
function showUnits(){modal(`<span class="eyebrow">NATIONAL INSTITUTIONS</span><h2>澄川单位名录 · ${UNITS.length.toLocaleString()}个</h2><p class="sub">仿照省、市、县工作部门命名，地区与负责人均为虚构。单位用于任职、调任和官员往来。</p><label>检索单位<input id="unit-query" type="text" placeholder="例如：财政局、教育厅、海宁省"></label><label>单位层级<select id="unit-level"><option value="">所有层级</option>${['县级','市级','省级','国家级'].map(x=>`<option>${x}</option>`).join('')}</select></label><p id="unit-summary" class="sub"></p><div id="unit-results"></div><div class="row"><button id="unit-prev">上一页</button><button id="unit-next">下一页</button></div>`);let page=0;const paint=()=>{const q=$('#unit-query').value.trim(),level=$('#unit-level').value,found=UNITS.filter(u=>(!level||u.level===level)&&(!q||(u.name+u.province+u.city+u.county).includes(q)));page=Math.max(0,Math.min(page,Math.max(0,Math.ceil(found.length/20)-1)));$('#unit-summary').textContent=`共${found.length}个匹配单位 · 第${page+1}/${Math.max(1,Math.ceil(found.length/20))}页`;$('#unit-results').innerHTML=found.slice(page*20,page*20+20).map(u=>{const head=unitHead(u);return `<article class="unit-row"><b>${esc(u.name)}</b><span class="badge">${u.level}</span><p class="sub">${u.province} ${u.city} ${u.county}<br>负责人：${head.name}${head.title}</p></article>`;}).join('')||'<p class="sub">没有匹配单位，请更换关键词。</p>';$('#unit-prev').disabled=page===0;$('#unit-next').disabled=(page+1)*20>=found.length;};$('#unit-query').oninput=()=>{page=0;paint();};$('#unit-level').onchange=()=>{page=0;paint();};$('#unit-prev').onclick=()=>{page--;paint();};$('#unit-next').onclick=()=>{page++;paint();};paint();}



function reviewHTML(review){if(!review?.lines?.length)return '';return '<section class="annual-recap"><h3>'+esc(review.age)+'岁 · 过去一年大事记</h3><ul>'+review.lines.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></section>';}
function historyHTML(item){const h=item.historySource;if(!h||typeof h!=='object')return '';const link=typeof h.url==='string'&&/^https:\/\//.test(h.url)?h.url:'#';return '<section class="history-note"><span class="eyebrow">历史借鉴 · 游戏改编</span><h3>'+esc(h.name)+'</h3><p>'+esc(h.fact)+'</p><p>'+esc(item.explanation||'')+'</p><a href="'+esc(link)+'" target="_blank" rel="noreferrer">查看历史来源 ↗</a></section>';}
function tutorial(){let step=0;const pages=[
['欢迎来到澄川','从出生开始，每天选择一种符合年龄的活动。德、智、体、美、劳相互促进；初始总点数相同，成长没有100点上限。','先选活动，再选一天／一周／一月／一年。快进保留每日属性结算，但减少观察汇报收益。'],
['试做一次小选择','班级科学记录与原来的猜测不同，怎么办？这只是练习，不影响存档。','年度关键抉择会自动暂停。可试听每个选项的金手指：明亮偏正向、悲伤偏负向，三个年龄曲库使用不限次。'],
['看见人生的重要变化','3岁进入幼儿园，6岁上小学。初中起的重要毕业阶段可自主选择是否继续求学。任职、择偶等节点也会等待你作决定。','升学与升迁会播报，插图下附过去一年大事记。可继续／跳过播报，之后也能到人生档案查看。'],
['保持健康，继续前行','低体力会带来疾病风险。身体力行帮助恢复；亲属也会衰老、患病和离世。退休后仍可继续生活。','五维全破100获得仙值；任一维度达1000后获取十倍，可按1比1兑换寿命，上限150岁。游戏自动保存在本浏览器，建议定期导出备份。']
];const finish=()=>{if(state){state.tutorialDone=true;save();}$('#modal').close();};const paint=()=>{const [title,text,note]=pages[step];modal('<span class="eyebrow">入门培训 · '+(step+1)+' / '+pages.length+'</span><h2>'+title+'</h2><p>'+text+'</p>'+(step===1?'<div class="choices"><button data-training="good">如实记录，再核查原因</button><button data-training="bad">改成和猜测一致的数字</button></div><p id="training-feedback" role="status"></p>':'')+'<p class="tutorial-note">'+note+'</p><div class="row"><button id="tutorial-back" class="smallbtn" '+(step===0?'disabled':'')+'>上一步</button><button id="tutorial-next" class="primary">'+(step===pages.length-1?'开始我的人生':'下一步')+'</button><button id="tutorial-skip" class="smallbtn">跳过教程</button></div>');$('#close-dialog').hidden=true;$('#tutorial-next').onclick=()=>{if(step<pages.length-1){step++;paint();}else finish();};$('#tutorial-back').onclick=()=>{step--;paint();};$('#tutorial-skip').onclick=finish;$('#modal').oncancel=e=>{e.preventDefault();finish();};document.querySelectorAll('[data-training]').forEach(b=>b.onclick=()=>{$('#training-feedback').textContent=b.dataset.training==='good'?'方向正确！尊重证据，才能修正判断。':'再想一想：保留真实结果，比让数字好看更重要。';});};paint();}
